import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Grid,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  CheckCircle as ImportedIcon,
  ErrorOutline as FailedIcon,
  ReportProblem as InvalidIcon,
  Replay as DuplicateIcon,
  WarningAmber as BillRequiredIcon,
} from '@mui/icons-material';
import type { LastAccountingImportResult } from './accountingImportResult';

interface AccountingImportSummaryProps {
  result: LastAccountingImportResult;
  onViewImported: () => void;
  onReviewBillRequired: () => void;
  onViewImportDetails: () => void;
  onViewAllImportedActivity?: () => void;
  onDownloadAuditWorkbook?: () => void;
}

const statusCards = (result: LastAccountingImportResult) => ([
  {
    key: 'imported',
    label: 'Imported successfully',
    count: result.totals.imported,
    icon: <ImportedIcon fontSize="small" color="success" />,
    color: 'success.main',
  },
  {
    key: 'billRequired',
    label: 'Bill required',
    count: result.totals.pendingBillUpload,
    icon: <BillRequiredIcon fontSize="small" color="warning" />,
    color: 'warning.main',
  },
  {
    key: 'duplicates',
    label: 'Duplicates',
    count: result.totals.duplicates,
    icon: <DuplicateIcon fontSize="small" color="action" />,
    color: 'text.secondary',
  },
  {
    key: 'invalid',
    label: 'Invalid',
    count: result.totals.invalid,
    icon: <InvalidIcon fontSize="small" color="warning" />,
    color: 'warning.dark',
  },
  {
    key: 'failed',
    label: 'Failed',
    count: result.totals.persistFailures,
    icon: <FailedIcon fontSize="small" color="error" />,
    color: 'error.main',
  },
]);

const AccountingImportSummary: React.FC<AccountingImportSummaryProps> = ({
  result,
  onViewImported,
  onReviewBillRequired,
  onViewImportDetails,
  onViewAllImportedActivity,
  onDownloadAuditWorkbook,
}) => {
  const cards = statusCards(result);
  const formatHint = result.detection?.format || result.importMeta?.format;
  const importedDisabled = result.totals.imported <= 0;
  const billRequiredDisabled = result.totals.pendingBillUpload <= 0;

  return (
    <Paper
      variant="outlined"
      sx={{ p: { xs: 2, sm: 2.5 }, mb: 2 }}
      aria-live="polite"
      aria-atomic="true"
    >
      <Typography variant="h6" component="h3" sx={{ fontWeight: 700 }}>
        Import complete
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        {result.fileName}
        {result.providerLabel ? ` · ${result.providerLabel}` : ''}
        {formatHint ? ` · ${formatHint}` : ''}
      </Typography>

      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
        {result.totals.received != null && (
          <Chip
            size="small"
            variant="outlined"
            label={`Records received: ${result.totals.received}`}
          />
        )}
        {result.totals.parsed != null && (
          <Chip
            size="small"
            variant="outlined"
            label={`Records parsed: ${result.totals.parsed}`}
          />
        )}
        {result.carbonAnalysisStatus === 'queued' && (
          <Chip
            size="small"
            color="info"
            variant="outlined"
            label="Carbon analysis is continuing in the background"
          />
        )}
        {result.carbonAnalysisStatus === 'skipped' && (
          <Chip
            size="small"
            variant="outlined"
            label="Carbon analysis skipped"
          />
        )}
        {result.actionRequired && (
          <Chip
            size="small"
            color="warning"
            variant="outlined"
            label="Some rows need bill upload"
          />
        )}
      </Stack>

      {result.message && (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
          {result.message}
        </Typography>
      )}

      <Grid container spacing={1.5} sx={{ mb: 2 }}>
        {cards.map((card) => (
          <Grid item xs={12} sm={6} md key={card.key}>
            <Card variant="outlined" sx={{ height: '100%' }}>
              <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.5 }}>
                  {card.icon}
                  <Typography variant="caption" color="text.secondary">
                    {card.label}
                  </Typography>
                </Stack>
                <Typography variant="h5" component="p" sx={{ fontWeight: 700, color: card.color }}>
                  {card.count}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={1}
        flexWrap="wrap"
        useFlexGap
      >
        <Button
          variant="contained"
          disabled={importedDisabled}
          onClick={onViewImported}
          aria-label="View imported transactions from this import"
        >
          View imported
        </Button>
        <Button
          variant="outlined"
          color="warning"
          disabled={billRequiredDisabled}
          onClick={onReviewBillRequired}
          aria-label="Review transactions that require a bill upload"
        >
          Review bill required
        </Button>
        <Button
          variant="outlined"
          onClick={onViewImportDetails}
          aria-label="View import details by category"
        >
          View import details
        </Button>
        {onDownloadAuditWorkbook && (
          <Button
            variant="contained"
            color="secondary"
            onClick={onDownloadAuditWorkbook}
            aria-label={`Download audit Excel for ${result.fileName}`}
          >
            Download audit Excel
          </Button>
        )}
      </Stack>

      {onViewAllImportedActivity && (
        <Box sx={{ mt: 1.5 }}>
          <Button
            size="small"
            variant="text"
            onClick={onViewAllImportedActivity}
            aria-label="View all imported activity, not only this import"
          >
            View all imported activity
          </Button>
          <Typography variant="caption" color="text.secondary" display="block">
            Opens all imported activity. It is not limited to this file.
          </Typography>
        </Box>
      )}
    </Paper>
  );
};

export default AccountingImportSummary;
